// 256 words x 16 bits, organised as 64 rows x 4 words (column mux 4:1)
logic [7:0] addr;
logic [5:0] row;          // which word line
logic [1:0] col;          // which word in the row
assign {row, col} = addr; // low bits = column

logic [11:0] addr;
logic [1:0]  bank_hi, bank_lo;
assign bank_hi = addr[11:10];   // blocks of 1024 words per bank
assign bank_lo = addr[1:0];     // word 0 → bank 0, word 1 → bank 1, …

// Width: 64 x 1K from four 16 x 1K - same address, one 16-bit slice each
module ram_64x1k (
  input  logic        clk, en, we,
  input  logic [9:0]  addr,
  input  logic [63:0] din,
  output logic [63:0] dout
);
  sp_ram #(.DW(16), .DEPTH(1024)) u_ram0 (.clk, .en, .we, .addr,
    .din(din[15: 0]), .dout(dout[15: 0]));
  sp_ram #(.DW(16), .DEPTH(1024)) u_ram1 (.clk, .en, .we, .addr,
    .din(din[31:16]), .dout(dout[31:16]));
  sp_ram #(.DW(16), .DEPTH(1024)) u_ram2 (.clk, .en, .we, .addr,
    .din(din[47:32]), .dout(dout[47:32]));
  sp_ram #(.DW(16), .DEPTH(1024)) u_ram3 (.clk, .en, .we, .addr,
    .din(din[63:48]), .dout(dout[63:48]));
endmodule

// Depth: 16 x 4K from four 16 x 1K - a decoder enables one bank
module ram_16x4k (
  input  logic        clk, en, we,
  input  logic [11:0] addr,
  input  logic [15:0] din,
  output logic [15:0] dout
);
  logic [1:0]  bank, bank_q;
  logic [15:0] q0, q1, q2, q3;

  assign bank = addr[11:10];

  sp_ram #(.DW(16), .DEPTH(1024)) u_bank0 (.clk, .we, .din,
    .en(en && bank == 2'd0), .addr(addr[9:0]), .dout(q0));
  sp_ram #(.DW(16), .DEPTH(1024)) u_bank1 (.clk, .we, .din,
    .en(en && bank == 2'd1), .addr(addr[9:0]), .dout(q1));
  sp_ram #(.DW(16), .DEPTH(1024)) u_bank2 (.clk, .we, .din,
    .en(en && bank == 2'd2), .addr(addr[9:0]), .dout(q2));
  sp_ram #(.DW(16), .DEPTH(1024)) u_bank3 (.clk, .we, .din,
    .en(en && bank == 2'd3), .addr(addr[9:0]), .dout(q3));

  // read data arrives one clock later: remember which bank was read
  always_ff @(posedge clk) if (en) bank_q <= bank;

  always_comb
    case (bank_q)
      2'd0:    dout = q0;
      2'd1:    dout = q1;
      2'd2:    dout = q2;
      default: dout = q3;
    endcase
endmodule
